{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林知予",
      "role": "protagonist",
      "identity": "省体操队队员（前世为国家队女子体操主教练）",
      "traits": ["冷静理智", "技术偏执", "嘴硬心软", "责任感强"],
      "overt_motivation": "帮助苏晚拿到平衡木项目世界冠军，阻止前世平衡木事故的发生",
      "covert_motivation": "弥补前世间接导致苏晚瘫痪的愧疚，获得自我救赎",
      "secret_fear": "平衡木事故再次发生，苏晚因为自己的缘故再次受伤断送职业生涯",
      "misperception_of_other": "以为苏晚没有重生，不知道前世的恩怨，自己的补偿行为是单方面的",
      "hidden_connection": "前世苏晚退役后一直匿名给林知予的体操启蒙基金捐款"
    },
    {
      "name": "苏晚",
      "role": "deuteragonist",
      "identity": "省体操队平衡木项目种子选手",
      "traits": ["外表软萌", "内心敏感", "观察力强", "嘴硬傲娇"],
      "overt_motivation": "远离林知予，避免重蹈前世被推下平衡木瘫痪的覆辙",
      "covert_motivation": "确认林知予前世推自己的真实原因，解开压在心底多年的结",
      "secret_fear": "再次信任林知予后被背叛，自己的体操生涯再次被迫中断",
      "misperception_of_other": "以为林知予是故意推自己坠木，今生接近自己有不可告人的目的",
      "hidden_connection": "前世一直暗恋林知予，坠木前正准备赛后给林知予送表白礼物"
    }
